package com.gerenciadorrural.modules.herd.api;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties; import com.fasterxml.jackson.databind.annotation.JsonDeserialize; import com.gerenciadorrural.modules.herd.application.*; import com.gerenciadorrural.modules.herd.domain.*; import com.gerenciadorrural.modules.organizations.api.ResolvedTenantContext; import com.gerenciadorrural.shared.tenancy.TenantContext; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/herd") public class HerdTransferController {private final TransferCurrentFarmAnimals service;private final TenantTransferLog transfers;public HerdTransferController(TransferCurrentFarmAnimals service,TenantTransferLog transfers){this.service=service;this.transfers=transfers;}@PostMapping("/animals/{id}/transfers")public ResponseEntity<Response> one(@ResolvedTenantContext TenantContext c,@PathVariable UUID id,@RequestBody Request r){return ok(service.one(c,id,r.operationId(),r.expectedVersion(),r.destinationFarmId(),r.destinationPaddockId(),r.occurredOn(),r.notes()));}@PostMapping("/transfers/batch")public ResponseEntity<Response> batch(@ResolvedTenantContext TenantContext c,@RequestBody BatchRequest r){return ok(service.batch(c,r.operationId(),r.destinationFarmId(),r.destinationPaddockId(),r.occurredOn(),r.notes(),r.animals()));}@GetMapping("/transfers")public ResponseEntity<PageResponse> list(@ResolvedTenantContext TenantContext c,@RequestParam(required=false)String direction,@RequestParam(required=false)UUID animalId,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer size,HttpServletRequest request){if(!Set.of("direction","animalId","page","size").containsAll(request.getParameterMap().keySet()))throw new HerdAnimalQueryException();String d=direction==null?"ALL":direction;if(!Set.of("IN","OUT","ALL").contains(d)||(page!=null&&page<0)||(size!=null&&(size<1||size>100)))throw new HerdAnimalQueryException();int s=size==null?20:size,p=page==null?0:page;return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(PageResponse.from(transfers.list(c,d,animalId,p,s),p,s));}@GetMapping("/transfers/{id}")public ResponseEntity<Item> detail(@ResolvedTenantContext TenantContext c,@PathVariable UUID id){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(Item.from(transfers.detail(c,id)));}private ResponseEntity<Response> ok(TransferCurrentFarmAnimals.Result x){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(Response.from(x));}@JsonIgnoreProperties(ignoreUnknown=false)@JsonDeserialize(using=HerdTransferRequestDeserializer.class)public record Request(UUID operationId,long expectedVersion,UUID destinationFarmId,UUID destinationPaddockId,LocalDate occurredOn,String notes){}@JsonIgnoreProperties(ignoreUnknown=false)@JsonDeserialize(using=HerdBatchTransferRequestDeserializer.class)public record BatchRequest(UUID operationId,UUID destinationFarmId,UUID destinationPaddockId,LocalDate occurredOn,String notes,List<TransferCurrentFarmAnimals.Animal> animals){}public record Farm(String id,String name){static Farm from(HerdTransferRepository.Farm x){return new Farm(x.id().toString(),x.name());}}public record Response(String operationId,Farm sourceFarm,Farm destinationFarm,PaddockItem destinationPaddock,int transferredCount,List<Version> animals){static Response from(TransferCurrentFarmAnimals.Result x){return new Response(x.operationId().toString(),Farm.from(x.sourceFarm()),Farm.from(x.destinationFarm()),PaddockItem.from(x.destinationPaddock()),x.transferredCount(),x.animals().stream().map(a->new Version(a.id().toString(),a.version())).toList());}}public record Version(String id,long version){}public record Item(String id,String operationId,String animalId,Farm sourceFarm,Farm destinationFarm,PaddockItem destinationPaddock,LocalDate occurredOn,Instant recordedAt,String actorUserId,long resultingVersion,String notes){static Item from(HerdTransferRepository.Row x){return new Item(x.id().toString(),x.operationId().toString(),x.animalId().toString(),new Farm(x.sourceFarmId().toString(),x.sourceFarmName()),new Farm(x.destinationFarmId().toString(),x.destinationFarmName()),x.destinationPaddockId()==null?null:new PaddockItem(x.destinationPaddockId().toString(),x.destinationPaddockName(),null,"ACTIVE",0),x.occurredOn(),x.recordedAt(),x.actorUserId()==null?null:x.actorUserId().toString(),x.resultingVersion(),x.notes());}}public record PageResponse(List<Item> items,int page,int size,long totalElements,int totalPages){static PageResponse from(HerdTransferRepository.Page x,int p,int s){return new PageResponse(x.items().stream().map(Item::from).toList(),p,s,x.total(),(int)Math.ceil((double)x.total()/s));}}}
